$store=__DIR__.'/room-state.json';$now=time();$ttl=30;
function clean_name($v){$v=trim((string)$v);$v=preg_replace('/\s+/',' ',$v);return mb_substr($v,0,24);}function clean_message($v){$v=trim((string)$v);$v=preg_replace('/\s+/',' ',$v);return mb_substr($v,0,140);}function default_state(){return ['event'=>'waiting','phase'=>'idle','current_manager'=>null,'current_region'=>null,'current_team'=>null,'assignments'=>[],'started_at'=>null,'completed_at'=>null,'updated_at'=>gmdate('c'),'presence'=>[],'messages'=>[]];}function load_locked($fp){rewind($fp);$raw=stream_get_contents($fp);if(!$raw)return default_state();$data=json_decode($raw,true);return is_array($data)?array_merge(default_state(),$data):default_state();}function save_locked($fp,$state){$state['updated_at']=gmdate('c');rewind($fp);ftruncate($fp,0);fwrite($fp,json_encode($state,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT));fflush($fp);}function prune_presence(&$state,$now,$ttl){if(!isset($state['presence'])||!is_array($state['presence']))$state['presence']=[];foreach($state['presence'] as $sid=>$p){if(!isset($p['last_seen'])||($now-(int)$p['last_seen'])>$ttl)unset($state['presence'][$sid]);}}function public_state($state){$people=array_values(array_map(function($p){return ['name'=>$p['name']??'Guest'];},$state['presence']??[]));usort($people,function($a,$b){return strcasecmp($a['name'],$b['name']);});return ['ok'=>true,'event'=>$state['event']??'waiting','phase'=>$state['phase']??'idle','current_manager'=>$state['current_manager']??null,'current_region'=>$state['current_region']??null,'current_team'=>$state['current_team']??null,'assignments'=>array_values($state['assignments']??[]),'started_at'=>$state['started_at']??null,'completed_at'=>$state['completed_at']??null,'updated_at'=>$state['updated_at']??null,'online_count'=>count($people),'people'=>$people,'messages'=>array_slice(array_values($state['messages']??[]),-100)];}
