am'=>$team,'region'=>$region,'time'=>gmdate('c')];usort($state['assignments'],function($a,$b){return ((int)$a['seq'])<=>((int)$b['seq']);});$state['event']='live';$state['phase']='assignment';$state['current_manager']=$manager;$state['current_region']=$region;$state['current_team']=$team;}elseif($action==='host_complete'||$action==='host_finalize'){if(count($state['assignments'])!==18){http_response_code(409);echo json_encode(['ok'=>false,'error'=>'draw_not_complete','assignments'=>count($state['assignments'])]);flock($fp,LOCK_UN);fclose($fp);exit;}$state['event']='completed';$state['phase']='idle';$state['completed_at']=gmdate('c');}else{http_response_code(400);echo json_encode(['ok'=>false,'error'=>'unknown_host_action']);flock($fp,LOCK_UN);fclose($fp);exit;}}else{$sid=preg_replace('/[^a-zA-Z0-9_-]/','',(string)($input['sid']??''));if(strlen($sid)<8||strlen($sid)>80){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'invalid_session']);flock($fp,LOCK_UN);fclose($fp);exit;}if($action==='join'||$action==='heartbeat'){$name=clean_name($input['name']??($state['presence'][$sid]['name']??''));if($name===''){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'name_required']);flock($fp,LOCK_UN);fclose($fp);exit;}$state['presence'][$sid]=['name'=>$name,'last_seen'=>$now];}elseif($action==='chat'){$name=clean_name($input['name']??($state['presence'][$sid]['name']??''));$text=clean_message($input['message']??'');if($name===''||$text===''){http_response_code(400);echo json_encode(['ok'=>false,'error'=>'invalid_message']);flock($fp,LOCK_UN);fclose($fp);exit;}$state['presence'][$sid]=['name'=>$name,'last_seen'=>$now];if(!isset($state['messages'])||!is_array($state['messages']))$state['messages']=[];$state['messages'][]=['id'=>bin2hex(random_bytes(6)),'name'=>$name,'message'=>$text,'time'=>gmdate('c')];if(count($state['messages'])>100)$state['messages']=array_slice($state['messages'],-100);}elseif($action==='leave'){unset($state['presence'][$sid]);}else{http_response_code(400);echo json_encode(['ok'=>false,'error'=>'unknown_action']);flock($fp,LOCK_UN);fclose($fp);exit;}}}save_locked($fp,$state);$response=public_state($state);flock($fp,LOCK_UN);fclose($fp);echo json_encode($response,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
